---@return cloudflare.memberships.Client
function Module.new(options) end

---@class cloudflare.memberships.Client
local Client = {}

---A client sharing this one's budget, credentials cache and tracer, with overrides.
---@param options cloudflare.memberships.Options
---@return cloudflare.memberships.Client
function Client:with(options) end

---Flush spans and release what the client holds.
function Client:close() end

---Remove the associated member from an account.
---
---`DELETE /memberships/{membership_id}`
---@param input cloudflare.memberships.DeleteMembershipRequest
---@return cloudflare.memberships.DeleteMembershipResponse? value
---@return distilled.Error? err
function Client:delete_membership(input) end

---Get a specific membership.
---
---`GET /memberships/{membership_id}`
---@param input cloudflare.memberships.GetMembershipRequest
---@return cloudflare.memberships.GetMembershipResponse? value
---@return distilled.Error? err
function Client:get_membership(input) end

---List memberships of accounts the user can access.
---
---`GET /memberships`
---@param input? cloudflare.memberships.ListMembershipsRequest
---@return cloudflare.memberships.ListMembershipsResponse? value
---@return distilled.Error? err
function Client:list_memberships(input) end

---List memberships of accounts the user can access.
---
---Every page, fetched as the loop asks for it.
---
---`GET /memberships`
---@param input? cloudflare.memberships.ListMembershipsRequest
---@return distilled.Iterator<cloudflare.memberships.ListMembershipsResponse>
function Client:list_memberships_pages(input) end

---List memberships of accounts the user can access.
---
---Every item of every page (`result`).
---
---`GET /memberships`
---@param input? cloudflare.memberships.ListMembershipsRequest
---@return distilled.Iterator<cloudflare.memberships.ListResultItem>
function Client:list_memberships_items(input) end

---Accept or reject this account invitation.
---
---`PUT /memberships/{membership_id}`
---@param input cloudflare.memberships.PutMembershipRequest
---@return cloudflare.memberships.PutMembershipResponse? value
---@return distilled.Error? err
function Client:put_membership(input) end

return Module
